            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x4EAE5FDBAFCC851FULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterF) ^ 0x4B0D36CD6B1A7BB1ULL) ^ aOUSaltB[(((511U - aIndex) + 121U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xF1A6F61713542359ULL), 23U);
