            aWandererC = aWandererC + (((RotL64(aScatter, 47U) + RotL64(aOrbiterE, 43U)) + aOrbiterA) + aWUSaltG[((aIndex + 63U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aPrevious, 43U) + aOrbiterG) + RotL64(aOrbiterK, 47U));
            aWandererI = aWandererI + (((RotL64(aIngress, 11U) + aOrbiterE) + RotL64(aOrbiterH, 30U)) + aWUSaltD[((aIndex + 427U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aScatter, 51U) + RotL64(aOrbiterD, 19U)) + aOrbiterC);
            aWandererG = aWandererG + (((RotL64(aIngress, 57U) + RotL64(aOrbiterH, 53U)) + aOrbiterC) + RotL64(aCarry, 57U));
            aWandererJ = aWandererJ ^ ((RotL64(aCross, 35U) + aOrbiterG) + RotL64(aOrbiterE, 23U));
            aWandererE = aWandererE + ((((RotL64(aPrevious, 39U) + aOrbiterA) + RotL64(aOrbiterF, 4U)) + RotL64(aCarry, 29U)) + aWUSaltF[((aIndex + 361U)) & S_SALT1]);
