            //
            aOrbiterF = ((aWandererE + RotL64(aIngress, 51U)) + 0xA9B147D2F7AAB040ULL) + aOASaltE[(((511U - aIndex) + 408U)) & S_SALT1];
            aOrbiterK = (aWandererA + RotL64(aCross, 47U)) + 0x34964781A4F40B02ULL;
            aOrbiterB = ((aWandererG + RotL64(aPrevious, 12U)) + 0x0DE4B8AA1C4C830CULL) + aOASaltG[(((511U - aIndex) + 349U)) & S_SALT1];
            aOrbiterA = (((aWandererK + RotL64(aScatter, 21U)) + RotL64(aCarry, 53U)) + 0x0C4D2EE54692A2CFULL) + aOASaltH[((aIndex + 33U)) & S_SALT1];
