            aOrbiterG = (aWandererF + RotL64(aScatter, 3U)) + 0x84078AEAC75B3962ULL;
            aOrbiterD = (aWandererI + RotL64(aPrevious, 27U)) + 0x4E979AE2B9791B6CULL;
            aOrbiterJ = ((aWandererD + RotL64(aIngress, 56U)) + RotL64(aCarry, 27U)) + 0x92F76626A4F80F61ULL;
            aOrbiterC = ((aWandererB + RotL64(aCross, 37U)) + 0x680DC9FD152F2D33ULL) + aOASaltA[((aIndex + 270U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x2C79A799B1A81588ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0xB1FA6B11E6C62D8DULL;
            aOrbiterB = RotL64((aOrbiterB * 0xA8AD3E826110E4DDULL), 39U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x0F358D570C3104BEULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0x4BC1CED9AE0D1AF1ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x0AC462F3970B90BFULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x9911FC14C41BAA83ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterB) ^ 0x4DB5132C5944F4D4ULL) ^ aOUSaltE[((aIndex + 262U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x11F72BF44886EC19ULL), 19U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0xA50546BA83CE3741ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterH) ^ 0x89F99B2FD7328320ULL) ^ aOUSaltB[(((511U - aIndex) + 1U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xB864B46C1212CEF7ULL), 29U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterC) + 0x461C336F5A85CDEFULL) + aOUSaltC[((aIndex + 230U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterJ) ^ 0xE2327EDC0C1AFB8AULL) ^ aOUSaltH[(((511U - aIndex) + 166U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xA9D93B55CC16B2D5ULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0xBC106E1AD4336990ULL;
