            aWandererA = aWandererA ^ (((RotL64(aCross, 23U) + aOrbiterJ) + RotL64(aOrbiterH, 19U)) + aWUSaltH[((aIndex + 449U)) & S_SALT1]);
            aWandererG = aWandererG + ((((RotL64(aPrevious, 41U) + aOrbiterG) + RotL64(aOrbiterC, 47U)) + RotL64(aCarry, 19U)) + aWUSaltA[(((511U - aIndex) + 173U)) & S_SALT1]);
