            aOrbiterD = (((aWandererG + RotL64(aCross, 51U)) + RotL64(aCarry, 43U)) + 0x580BDD474F85AEC8ULL) + aOASaltA[(((511U - aIndex) + 447U)) & S_SALT1];
            aOrbiterK = (aWandererI + RotL64(aScatter, 43U)) + 0x283C215B0CD4CA23ULL;
            aOrbiterJ = (aWandererC + RotL64(aCross, 23U)) + 0x0D9F839AA45A5C4AULL;
            aOrbiterC = ((aWandererD + RotL64(aIngress, 13U)) + 0xFB7BCAABB6B5399EULL) + aOASaltH[(((511U - aIndex) + 509U)) & S_SALT1];
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0xD1CA06F0EE5FACBCULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterE) ^ 0xC5F7650338F50672ULL) ^ aOUSaltF[((aIndex + 189U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x70552BE40F21DD7FULL), 41U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x547C67BF8BA0F0B6ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0xE3555F06496B34EDULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1A1E37BCF0A3D7EFULL), 13U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0xCC4B3296F62E2910ULL) + aOUSaltA[(((511U - aIndex) + 54U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterK) ^ 0xB30FD83B22AF3D54ULL) ^ aOUSaltH[((aIndex + 10U)) & S_SALT1];
