            //
            aOrbiterA = (aWandererA + RotL64(aIngress, 47U)) + 0x23697D4098C180D0ULL;
            aOrbiterD = (aWandererI + RotL64(aPrevious, 39U)) + 0xB94508E17F3705C5ULL;
            aOrbiterE = ((aWandererG + RotL64(aCross, 27U)) + 0x574C4099A60B12DDULL) + aOASaltG[((aIndex + 27U)) & S_SALT1];
