            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterD = (((aWandererG + RotL64(aScatter, 41U)) + RotL64(aCarry, 53U)) + 0xF5B6E17E56A8F744ULL) + aOASaltH[(((511U - aIndex) + 151U)) & S_SALT1];
