            aOrbiterF = (((aWandererI + RotL64(aPrevious, 26U)) + RotL64(aCarry, 41U)) + 0x2BA82BF2E62BB4D8ULL) + aOASaltB[(((511U - aIndex) + 13U)) & S_SALT1];
