            aOrbiterH = (((aWandererB + RotL64(aCross, 5U)) + RotL64(aCarry, 27U)) + 0x1CD766A90490723AULL) + aOASaltD[((aIndex + 392U)) & S_SALT1];
            aOrbiterA = ((aWandererE + RotL64(aScatter, 47U)) + 0x90C1D267234BC549ULL) + aOASaltE[(((511U - aIndex) + 380U)) & S_SALT1];
            aOrbiterG = (aWandererK + RotL64(aIngress, 11U)) + 0x52C8BF90A848F704ULL;
            aOrbiterI = (aWandererC + RotL64(aPrevious, 30U)) + 0xCEED9CAD68424B12ULL;
            //
            aOrbiterD = ((aOrbiterD + aOrbiterC) + 0xD4630E422AD896E5ULL) + aOUSaltC[((aIndex + 26U)) & S_SALT1];
