            aWandererC = aWandererC + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterJ, 14U)) + aOrbiterE) + aWUSaltF[(((511U - aIndex) + 260U)) & S_SALT1]);
            aWandererE = aWandererE ^ (((RotL64(aScatter, 13U) + RotL64(aOrbiterE, 57U)) + aOrbiterD) + aWUSaltB[((aIndex + 308U)) & S_SALT1]);
            aWandererA = aWandererA + ((RotL64(aCross, 57U) + RotL64(aOrbiterC, 43U)) + aOrbiterF);
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 28U) + RotL64(aOrbiterH, 5U)) + aOrbiterK);
