            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x70E78751A612FB67ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xB039522CA6BB34A4ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x81D27D662E49B3B7ULL), 3U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x3DEF02165021F16DULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0xE436E825BA5729A0ULL) ^ aOUSaltE[((aIndex + 231U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xD31DD93B35072475ULL), 29U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x232EF0612BE2D232ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0xB9E40C2409C3AA27ULL;
