            //
            aOrbiterB = (((aWandererF + RotL64(aCross, 19U)) + RotL64(aCarry, 11U)) + 0x94A9E5750E079A0DULL) + aOASaltH[((aIndex + 341U)) & S_SALT1];
            aOrbiterI = (aWandererJ + RotL64(aPrevious, 60U)) + 0x421565215A8C3679ULL;
            aOrbiterF = (aWandererD + RotL64(aScatter, 35U)) + 0xBD9F0F40A48F72A8ULL;
            aOrbiterD = (((aWandererI + RotL64(aIngress, 47U)) + RotL64(aCarry, 53U)) + 0xE6268EE3961D299BULL) + aOASaltE[(((511U - aIndex) + 423U)) & S_SALT1];
            aOrbiterE = ((aWandererC + RotL64(aPrevious, 27U)) + 0xF1F39F44E254EC2DULL) + aOASaltG[(((511U - aIndex) + 495U)) & S_SALT1];
            aOrbiterH = ((aWandererK + RotL64(aScatter, 13U)) + RotL64(aCarry, 35U)) + 0xD98C95587B3E35B9ULL;
            aOrbiterG = ((aWandererB + RotL64(aCross, 41U)) + 0x91DE30C83D665771ULL) + aOASaltD[(((511U - aIndex) + 291U)) & S_SALT1];
