            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xBA3CD4ECA1449835ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x14B04762CB7020D3ULL), 57U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x2C70EAD619EE6930ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterE) ^ 0xCFD31DB3C884684AULL) ^ aOUSaltA[(((511U - aIndex) + 480U)) & S_SALT1];
