            aOrbiterE = RotL64((aOrbiterE * 0x63A55CF2DF6C1465ULL), 47U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterF) + 0x9E97E6396985C1D6ULL) + aOUSaltB[((aIndex + 56U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0xEC82D34BA639C95CULL;
