            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0xC3DF8D9922817A0CULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0x83BA651308962C52ULL) ^ aOUSaltD[(((511U - aIndex) + 220U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x52A22D9816501D01ULL), 35U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0x86BA29664DE5B82DULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0x470AF097E5A8518CULL) ^ aOUSaltG[((aIndex + 103U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x13C555DA21177B63ULL), 19U);
            //
            aIngress = RotL64(aOrbiterI, 53U) ^ aOrbiterH;
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterB, 27U));
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterF, 19U));
            aIngress = aIngress + RotL64(aOrbiterE, 5U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererF = aWandererF + ((RotL64(aIngress, 21U) + RotL64(aOrbiterH, 28U)) + aOrbiterD);
