            aIngress = TwistMix64::DiffuseA((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 10647U)) & S_BLOCK1], 27U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 15577U)) & S_BLOCK1], 11U));
            aCross ^= (RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 15917U)) & S_BLOCK1], 42U) ^ RotL64(aPlasmaLaneD[((aIndex + 10065U)) & S_BLOCK1], 3U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 47U) + RotL64(aCarry, 60U)) ^ (RotL64(aCross, 35U) + RotL64(aIngress, 11U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterE = ((aWandererE + RotL64(aPrevious, 39U)) + 0xEAA026B2BF5FD2D1ULL) + aOASaltH[(((511U - aIndex) + 107U)) & S_SALT1];
            aOrbiterB = ((aWandererK + RotL64(aScatter, 13U)) + 0xE685F093BE980D97ULL) + aOASaltG[(((511U - aIndex) + 326U)) & S_SALT1];
            aOrbiterI = ((aWandererI + RotL64(aIngress, 29U)) + RotL64(aCarry, 21U)) + 0x252B956FA1B753F8ULL;
            aOrbiterH = ((aWandererF + RotL64(aCross, 23U)) + 0x495D0AD4291FAC34ULL) + aOASaltA[((aIndex + 338U)) & S_SALT1];
            aOrbiterC = (((aWandererJ + RotL64(aScatter, 3U)) + RotL64(aCarry, 3U)) + 0xCBA6FB9B78AAA44BULL) + aOASaltB[(((511U - aIndex) + 331U)) & S_SALT1];
            aOrbiterK = ((aWandererA + RotL64(aCross, 54U)) + 0x7AB4E8552D2B18BAULL) + aOASaltC[(((511U - aIndex) + 166U)) & S_SALT1];
            aOrbiterA = ((aWandererD + RotL64(aPrevious, 47U)) + RotL64(aCarry, 41U)) + 0x6A1094B86AB20B3DULL;
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0x4B9782DD39946EDFULL) + aOUSaltB[((aIndex + 103U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xA950E3CCBECB52F7ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x952EAF0E14D04F3FULL), 23U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x863A24FEBD55DE93ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x050AF512B8E1ED2EULL;
            aOrbiterC = RotL64((aOrbiterC * 0x7693CA3B8F17C901ULL), 51U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0x0618E29B53255AFEULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x7E1C424B64BB52F0ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xB2284CF80902B8DDULL), 43U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0xAD08F0D80C723133ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0x91E1FD43F549942CULL;
            aOrbiterE = RotL64((aOrbiterE * 0xD4D50EA4A2797E07ULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0x1FDF470D45FBDC07ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0xAC89E41405BDD02EULL;
            aOrbiterK = RotL64((aOrbiterK * 0x6A651410297D3F09ULL), 35U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterC) + 0x86DEEA551D54A23BULL) + aOUSaltE[((aIndex + 185U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterB) ^ 0xB7C0CDCB2381D5C4ULL) ^ aOUSaltF[((aIndex + 259U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xA9B1BA452C16BC77ULL), 11U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0xCD0ABCDDF5842751ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0x325C095041EEB310ULL) ^ aOUSaltH[(((511U - aIndex) + 213U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xB317BC2F4CB1D6B5ULL), 29U);
            //
            aIngress = aOrbiterB ^ RotL64(aOrbiterC, 3U);
            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterE, 57U));
            aIngress = aIngress + (RotL64(aOrbiterK, 23U) ^ aOrbiterH);
            aIngress = aIngress + RotL64(aOrbiterI, 47U);
