            aCarry = aCarry + (aWandererA ^ RotL64(aWandererI, 50U));
            aCarry = aCarry + (RotL64(aWandererG, 27U) ^ aWandererF);
            aCarry = aCarry + (aWandererJ ^ RotL64(aWandererC, 53U));
            aCarry = aCarry + RotL64(aWandererD, 43U);
